// Fresh Play game, box opened once and its cards created. Back up progress first (README).
if(!UnityEditor.EditorApplication.isPlaying||!GameplayUIController.Instance.IsBookListOpen)throw new System.Exception("Open a fresh box and let a frame create its cards.");
int checks=0;void Check(bool ok,string message){if(!ok)throw new System.Exception("FAIL: "+message);checks++;}
T Find<T>() where T:UnityEngine.Object=>UnityEngine.Object.FindFirstObjectByType<T>(UnityEngine.FindObjectsInactive.Include);
GameObject Named(string n)=>UnityEngine.Object.FindObjectsByType<Transform>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).Single(t=>t.name==n).gameObject;
var list=Find<BookListUI>();var selection=Find<BookSelectionController>();var hand=Find<HandItemController>();var popup=Find<BookPopUpController>();var ui=GameplayUIController.Instance;var scroll=Named("Scroll View").GetComponent<UnityEngine.UI.ScrollRect>();
Find<BookPlacementTutorial>().Dismiss();foreach(var audio in UnityEngine.Object.FindObjectsByType<AudioSource>(UnityEngine.FindObjectsSortMode.None))audio.volume=0;
var cards=UnityEngine.Object.FindObjectsByType<BookButton>(UnityEngine.FindObjectsInactive.Include,UnityEngine.FindObjectsSortMode.None).OrderBy(b=>b.transform.GetSiblingIndex()).ToArray();var byName=cards.ToDictionary(b=>b.BookSprite.name);var originalIds=cards.Select(b=>b.GetInstanceID()).ToArray();
Check(hand.BookCount==0&&cards.Length==140&&list.ActiveColorIndex==-1&&list.GetRemainingCount()==140,"Fresh list contains all 140 books");
void Filter(int color){Named("BookColorFilter"+(color+1)).GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Check(list.ActiveColorIndex==color,"Filter switches to "+color);}
BookButton[] Visible()=>cards.Where(b=>b!=null&&b.gameObject.activeInHierarchy).ToArray();
for(int c=0;c<8;c++){Filter(c);Check(Visible().Length==BookColorUtility.GetShelfSlotCount(c)&&Visible().All(b=>BookColorUtility.GetColorIndexFromSpriteName(b.BookSprite.name)==c),"Only the requested color is visible");Check(list.GetRemainingCount(c)==BookColorUtility.GetShelfSlotCount(c),"Color count matches the box");Check(Enumerable.Range(0,9).Count(i=>Named("BookColorFilter"+i).transform.Find("FilterSelected").gameObject.activeSelf)==1,"Exactly one active filter marker");}
list.ShowColor(-2);list.ShowColor(8);Check(list.ActiveColorIndex==7,"Invalid filters leave the current view intact");Filter(-1);
Check(Visible().Select(b=>b.GetInstanceID()).SequenceEqual(originalIds),"Filtering keeps the same cards and random order");
scroll.verticalNormalizedPosition=0;scroll.velocity=new Vector2(0,350);Filter(0);Check(Mathf.Abs(scroll.verticalNormalizedPosition-1)<.001f&&scroll.velocity==Vector2.zero,"Switching color returns to the first row and stops momentum");byName["Green01"].SendSprite();byName["Green02"].OnPointerEnter(null);Filter(1);
Check(selection.SelectedCount==1&&byName["Green01"].IsSelected&&!byName["Green01"].gameObject.activeSelf,"Selection survives being hidden by another color");
var hoveredImage=new UnityEditor.SerializedObject(byName["Green02"]).FindProperty("_bookImage").objectReferenceValue as UnityEngine.UI.Image;Check(hoveredImage.color==Color.white,"Filtering removes a stale hover tint");byName["Green03"].SendSprite();Check(selection.SelectedCount==1,"Hidden cards cannot be selected through their callback");
byName["Blue01"].SendSprite();byName["Blue02"].SendSprite();Filter(3);byName["Red01"].SendSprite();
Check(selection.SelectedCount==4&&selection.CountSelectedOutsideColor(3)==3&&Named("SelectionHintLabel").GetComponent<TMPro.TMP_Text>().text.Contains("ほかの色で3冊"),"Footer explains selections outside the visible filter");
Filter(0);Check(byName["Green01"].IsSelected,"Returning to a color restores its selected highlight");byName["Green01"].SendSprite();Check(selection.SelectedCount==3,"A restored selected book can be deselected");
Named("ClearSelectionButton").GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Check(selection.SelectedCount==0&&cards.All(b=>!b.IsSelected),"Clear removes visible and hidden selections");
var mixed=new[]{"Green01","Blue01","Beige01","Red01","Purple01","Brown01","White01","Black01","Green02"};
foreach(string name in mixed){Filter(BookColorUtility.GetColorIndexFromSpriteName(name));byName[name].SendSprite();}
Check(selection.SelectedCount==9&&Named("SelectionHintLabel").GetComponent<TMPro.TMP_Text>().text.Contains("上限")&&selection.CountSelectedOutsideColor(0)==7,"The nine-book limit applies across all colors");byName["Green03"].SendSprite();Check(selection.SelectedCount==9&&!byName["Green03"].IsSelected,"A tenth book is rejected across filters");
selection.ShowSelectionConfirmation();var images=new UnityEditor.SerializedObject(popup).FindProperty("_bookImages");var shown=Enumerable.Range(0,9).Select(i=>(images.GetArrayElementAtIndex(i).objectReferenceValue as UnityEngine.UI.Image).sprite.name).ToArray();Check(shown.SequenceEqual(mixed),"Confirmation includes hidden selections in their selection order");
Named("BookColorFilter0").GetComponent<UnityEngine.UI.Button>().onClick.Invoke();Check(list.ActiveColorIndex==0&&popup.IsOpen,"Confirmation prevents changing the filter behind it");ui.Back();Check(selection.SelectedCount==9&&!popup.IsOpen&&list.ActiveColorIndex==0,"Back preserves filter and every selected book");
selection.ShowSelectionConfirmation();selection.TakeSelectedBooks();Check(hand.BookCount==9&&hand.Books.Select(b=>b.Sprite.name).SequenceEqual(mixed)&&list.GetRemainingCount()==131,"Taking mixed colors updates counts before deferred destruction");
for(int c=0;c<8;c++)Check(list.GetRemainingCount(c)==BookColorUtility.GetShelfSlotCount(c)-(c==0?2:1),"Taken books leave their own color count");
ui.OpenBookList();Filter(-1);Check(Visible().Length==131&&!Visible().Any(b=>mixed.Contains(b.BookSprite.name)),"Taken books stay out of every filter");Filter(1);byName["Blue02"].SendSprite();Check(selection.SelectedCount==0&&!Named("ConfirmSelectionButton").GetComponent<UnityEngine.UI.Button>().interactable,"Full hands block selection but allow browsing by color");
for(int i=0;i<3;i++){int previous=list.ActiveColorIndex;ui.CloseBookList();ui.OpenBookList();Check(list.ActiveColorIndex==previous,"Reopening keeps the last filter");Filter(i);Check(selection.SelectedCount==0,"Reopening retains no stale selection or duplicate toggle");}
var slots=UnityEngine.Object.FindObjectsByType<BookSlot>(UnityEngine.FindObjectsSortMode.None).OrderBy(s=>s.SlotIndex).ToArray();
void PlaceAll(){ui.CloseBookList();while(hand.BookCount>0){var book=hand.Books[0];hand.SelectBook(0);Check(HandBookPlacementController.Instance.TryPlaceBook(slots[book.CorrectSlotIndex]),"Place owned book without returning it to the box");}}
void Take(string[] names){ui.OpenBookList();Filter(-1);foreach(string name in names)byName[name].SendSprite();Check(selection.SelectedCount==names.Length,"Select intended available books");selection.ShowSelectionConfirmation();selection.TakeSelectedBooks();}
PlaceAll();Take(Enumerable.Range(3,9).Select(i=>"Green"+i.ToString("D2")).ToArray());PlaceAll();Take(Enumerable.Range(12,7).Select(i=>"Green"+i.ToString("D2")).ToArray());PlaceAll();
ui.OpenBookList();Filter(0);Check(list.GetRemainingCount(0)==0&&list.GetRemainingCount()==115&&Visible().Length==0,"One exhausted color has zero cards and an accurate total");Check(Named("BookFilterEmptyState").activeSelf&&Named("BookFilterEmptyMessage").GetComponent<TMPro.TMP_Text>().text.Contains("この色"),"Empty-color message explains how to choose another filter");Check(Named("SelectionHintLabel").GetComponent<TMPro.TMP_Text>().text.Contains("ほかの色"),"Empty-color footer also directs to the filters");Filter(-1);Check(Visible().Length==115&&!Named("BookFilterEmptyState").activeSelf,"All colors recovers the remaining books");
var remaining=Visible().Select(b=>b.BookSprite.name).ToArray();
for(int offset=0;offset<remaining.Length;offset+=9){var batch=remaining.Skip(offset).Take(9).ToArray();Take(batch);if(offset+9<remaining.Length)PlaceAll();}
ui.OpenBookList();Filter(0);Check(list.GetRemainingCount()==0&&Enumerable.Range(0,8).All(c=>list.GetRemainingCount(c)==0)&&Visible().Length==0,"All-box exhaustion updates all nine counts");Check(Named("BookFilterEmptyState").activeSelf&&Named("BookFilterEmptyMessage").GetComponent<TMPro.TMP_Text>().text.Contains("箱の本はすべて"),"Fully empty box has its own explanation");
Check(Named("SelectionHintLabel").GetComponent<TMPro.TMP_Text>().text.Contains("閉じる"),"Empty-box footer directs back to the shelves");
Check(hand.BookCount==7&&slots.Count(s=>s.IsFilled)==133&&selection.SelectedCount==0,"All 140 books still exist in hand or on shelves");
var expected=GameProgressData.Empty();expected.hand=hand.Books.Select(b=>b.Sprite.name).ToArray();expected.placed=byName.Keys.Except(expected.hand).Select(name=>{BookColorUtility.TryGetBookIndex(name,out int index);return new SavedBookPlacement{book=name,slot=index};}).OrderBy(b=>b.slot).ToArray();Check(expected.IsValid(),"Expected empty-box progress is valid");System.IO.File.WriteAllText(".utmp/save-smoke-expected.json",JsonUtility.ToJson(expected));
return new{passed=checks,remaining=list.GetRemainingCount(),placed=133,hand=7,activeColor=list.ActiveColorIndex};
